import{_ as a,o as e,c as i,a2 as d}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Git 协作与提交边界","description":"用小而完整的提交、清晰分支和可审阅 diff，让多人协作更容易回顾、测试和回滚。","frontmatter":{"title":"Git 协作与提交边界","description":"用小而完整的提交、清晰分支和可审阅 diff，让多人协作更容易回顾、测试和回滚。"},"headers":[],"relativePath":"engineering/git-workflow.md","filePath":"engineering/git-workflow.md","lastUpdated":1786262003000}'),r={name:"engineering/git-workflow.md"};function n(l,t,o,s,p,h){return e(),i("div",null,[...t[0]||(t[0]=[d(`<h1 id="git-协作与提交边界" tabindex="-1">Git 协作与提交边界 <a class="header-anchor" href="#git-协作与提交边界" aria-label="Permalink to &quot;Git 协作与提交边界&quot;">​</a></h1><p>Git 的价值不只是保存代码版本，更是让团队能回答：改了什么、为什么改、如何验证、出问题怎样回退。好的协作习惯从控制一次提交的边界开始。</p><h2 id="一个提交只完成一个可描述的变化" tabindex="-1">一个提交只完成一个可描述的变化 <a class="header-anchor" href="#一个提交只完成一个可描述的变化" aria-label="Permalink to &quot;一个提交只完成一个可描述的变化&quot;">​</a></h2><p>理想提交能用一句动词开头的话说明，例如“补充订单取消的权限校验”或“调整文章列表的空状态”。格式化、重命名和行为修改最好拆开，否则评审和回滚都会变困难。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>好：修复筛选条件切换后旧请求覆盖结果</span></span>
<span class="line"><span>差：修改页面、接口、样式和配置</span></span></code></pre></div><p>提交前检查暂存区，而不是默认把整个工作区都加入。这样能避免调试文件、个人配置和无关修改混入历史。</p><h2 id="分支表达工作目的" tabindex="-1">分支表达工作目的 <a class="header-anchor" href="#分支表达工作目的" aria-label="Permalink to &quot;分支表达工作目的&quot;">​</a></h2><p>功能、修复和实验应在独立分支完成。分支名称包含日期或任务语义，让其他人能迅速判断它的背景；长期分支定期合入主线，减少最后一次合并的冲突规模。</p><table tabindex="0"><thead><tr><th>时机</th><th>建议动作</th></tr></thead><tbody><tr><td>开始一项独立需求</td><td>从最新主线创建功能分支</td></tr><tr><td>发现无关改动</td><td>暂存、拆分或与负责人确认</td></tr><tr><td>准备评审</td><td>整理提交、补足验证说明</td></tr><tr><td>合并后出现问题</td><td>用小提交定位并可控回退</td></tr></tbody></table><h2 id="评审的是行为-不只是代码风格" tabindex="-1">评审的是行为，不只是代码风格 <a class="header-anchor" href="#评审的是行为-不只是代码风格" aria-label="Permalink to &quot;评审的是行为，不只是代码风格&quot;">​</a></h2><p>提交描述应包含改动原因、影响范围和验证方式。评审时优先检查输入边界、权限、失败路径、数据一致性和兼容性；格式问题交给自动化工具。</p><h2 id="提交前的最小清单" tabindex="-1">提交前的最小清单 <a class="header-anchor" href="#提交前的最小清单" aria-label="Permalink to &quot;提交前的最小清单&quot;">​</a></h2><ul><li><code>git status</code> 确认暂存区只有本次改动。</li><li>查看 diff，重点检查删除、配置和敏感信息。</li><li>运行与改动相称的构建、测试或静态检查。</li><li>提交说明写明结果与原因，而不是只写“update”。</li></ul><p>小而完整的提交会成为未来排障、回滚和理解系统的可靠路标。</p>`,14)])])}const f=a(r,[["render",n]]);export{u as __pageData,f as default};
